package remframework.geometry.discovery;
import org.joml.Vector3d;
import java.util.*;
public final class GeometryTestSession {
    private final GeometryConfiguration configuration;private final GeometryTestRequest request;
    public GeometryTestSession(GeometryConfiguration configuration,GeometryTestRequest request){if(!configuration.id().equals(request.configurationId()))throw new IllegalArgumentException("Selected configuration ID does not match the test request.");this.configuration=configuration;this.request=request;}
    public GeometryTestResult run(){FixedDegreeGraph graph=new FixedDegreeGraph(configuration.nodeCount(),configuration.exactDegree(),configuration.edges(),configuration.canonicalGraphLabel());GeometryRealization best=null;for(int attempt=0;attempt<request.initialRealizations();attempt++){long seed=request.randomSeed()+attempt;DynamicElasticSettings settings=DynamicElasticSettings.defaults(request.targetEdgeLength(),seed).withMaximumIterations(Math.min(request.searchLimit(),request.relaxationSettings().maximumIterations())).withCanonicalGeometry(DynamicElasticCanonicalGeometrySettings.disabled());List<DynamicElasticNode> initial=initialize(configuration.nodeCount(),request.dimension(),request.targetEdgeLength(),seed);DynamicElasticResult result=new DynamicElasticSession(graph,settings,initial).runUntilFinished();List<Vector3d> start=result.initialNodes().stream().map(n->new Vector3d(n.position())).toList(),end=result.finalNodes().stream().map(n->new Vector3d(n.position())).toList();GeometryRealizationStatus status=result.resultStatus()==DynamicElasticResultStatus.STABLE_CANDIDATE_FOUND?GeometryRealizationStatus.REALIZED:result.resultStatus()==DynamicElasticResultStatus.NUMERICAL_FAILURE?GeometryRealizationStatus.NUMERICAL_FAILURE:GeometryRealizationStatus.NO_REALIZATION_FOUND_WITHIN_SEARCH_LIMITS;var code=status==GeometryRealizationStatus.REALIZED?GeometryConfigurationStatusCode.GEOMETRICALLY_REALIZED:status==GeometryRealizationStatus.NUMERICAL_FAILURE?GeometryConfigurationStatusCode.NUMERICAL_FAILURE:GeometryConfigurationStatusCode.NO_REALIZATION_FOUND_WITHIN_SEARCH_LIMITS;var d=status==GeometryRealizationStatus.REALIZED?GeometryConfigurationDiagnostic.info(GeometryConfigurationStage.GEOMETRY_REALIZATION,code,"Geometrically realized","Equal connected-edge lengths reached numerical equilibrium; topology remained fixed."):GeometryConfigurationDiagnostic.stop(GeometryConfigurationStage.GEOMETRY_REALIZATION,code,"No realization found within search limits","The numerical search did not find a realization; this is not proof of non-embeddability.");best=new GeometryRealization(seed,request.dimension(),start,end,result.metrics().meanDistanceAccuracy(),result.metrics().maximumNodeSpeed(),status==GeometryRealizationStatus.REALIZED,result.metrics().minimumObservedNonNeighborDistance()>0,result.metrics().edgeClearanceViolations()==0,effectiveDimension(end),status,List.of(d));if(best.converged())break;}
        if(!best.converged()){GeometryConfigurationStatus s=GeometryConfigurationStatus.of(best.diagnostics().get(0));return new GeometryTestResult(configuration.id(),configuration.graphSymmetry(),best,null,null,null,AreaResult.unavailable(s),VolumeResult.unavailable(s),GeometryOptimizationResult.notAttempted(),s);}
        FaceDerivationResult faces=new FaceDerivationPipeline().derive(configuration,best);ClosedBoundaryResult boundary=new ClosedBoundaryValidator().validate(configuration,best,faces);GeometricSymmetryResult symmetry=new GeometricSymmetryAnalyzer().analyze(configuration,best);GeometryMeasureCalculator measures=new GeometryMeasureCalculator();AreaResult area=measures.area(best,boundary);VolumeResult volume=measures.volume(best,boundary);GeometryConfigurationStatus status=boundary.closed()?GeometryConfigurationStatus.of(GeometryConfigurationDiagnostic.info(GeometryConfigurationStage.COMPLETE,GeometryConfigurationStatusCode.VALID_CANDIDATE,"Valid candidate","A realization and unique closed boundary were established; eligible measures were calculated.")):boundary.status();return new GeometryTestResult(configuration.id(),configuration.graphSymmetry(),best,faces,boundary,symmetry,area,volume,GeometryOptimizationResult.notAttempted(),status);}
    private List<DynamicElasticNode> initialize(int n,GeometryEmbeddingDimension dimension,double length,long seed){SplittableRandom random=new SplittableRandom(seed);List<DynamicElasticNode> r=new ArrayList<>();for(int i=0;i<n;i++){Vector3d p;if(i==0)p=new Vector3d();else if(i==1)p=new Vector3d(length,0,0);else if(dimension==GeometryEmbeddingDimension.TWO_D){double angle=2*Math.PI*i/n;p=new Vector3d(length*Math.cos(angle),length*Math.sin(angle),0);}else p=new Vector3d(random.nextDouble(-length,length),random.nextDouble(-length,length),random.nextDouble(-length,length));r.add(new DynamicElasticNode(i,p,new Vector3d(),i<2));}return r;}
    private int effectiveDimension(List<Vector3d> p){double z=p.stream().mapToDouble(v->Math.abs(v.z)).max().orElse(0);if(z<1e-7)return 2;return 3;}
}
